import{_ as i,C as n,o as a,c as o,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"A Dynamic Integration Needs Five Boundaries, Not One Permission Switch","description":"","frontmatter":{"title":"A Dynamic Integration Needs Five Boundaries, Not One Permission Switch","date":"2026-08-13","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How should an extensible tool runtime keep a dynamic local integration bounded and reviewable?","summary":"A local helper that produces dynamic MCP HTTP headers is governed across scope, ownership, lifetime, resource use and observability. The useful pattern is not the helper itself, but treating dynamic integration as an explicit extension point with several independent boundaries.","sources":"research/analysis/Q-20260813-03-extension-boundary.md","item_id":"Q-20260813-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-13-bounded-extension-point-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-13-bounded-extension-point.md","filePath":"en/engineering/2026-08-13-bounded-extension-point.md","lastUpdated":1786634417000}'),c={name:"en/engineering/2026-08-13-bounded-extension-point.md"};function l(d,e,h,u,p,m){const t=n("ArticleCover");return a(),o("div",null,[r(t,{image:"/assets/covers/daily-2026-08-13-bounded-extension-point-cover.png",kicker:"Open-source Engineering · Daily Research",title:"A Dynamic Integration Needs Five Boundaries, Not One Permission Switch",summary:"A local helper that produces dynamic MCP HTTP headers is governed across scope, ownership, lifetime, resource use and observability. The useful pattern is not the helper itself, but treating dynamic integration as an explicit extension point with several independent boundaries.",version:"Q-20260813-03",status:"Daily Runtime V5 · 2026-08-13",languageHref:"/zh/engineering/2026-08-13-bounded-extension-point",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-dynamic-integration-needs-five-boundaries-not-one-permission-switch" tabindex="-1">A Dynamic Integration Needs Five Boundaries, Not One Permission Switch <a class="header-anchor" href="#a-dynamic-integration-needs-five-boundaries-not-one-permission-switch" aria-label="Permalink to &quot;A Dynamic Integration Needs Five Boundaries, Not One Permission Switch&quot;">​</a></h1><p>An extensible tool runtime often begins with a small request: run one local helper and use its output to decorate outbound requests. The code may look like configuration glue. The security and reliability surface is much larger.</p><p>The selected Codex implementation allows a local helper to supply dynamic HTTP headers for a streamable-HTTP MCP connection. Around that capability it establishes several separate controls: local-context admission, managed-policy checks, origin scoping, reserved-header ownership, bounded execution, process cleanup, cached materialization, redirect stopping and redacted inspection.</p><p>The important engineering lesson is not “shell helpers are safe.” The evidence does not support that claim. It is that a dynamic integration should be represented as an <strong>explicitly bounded extension point</strong>, not as an ordinary string-valued setting protected by one allow/deny switch.</p><h2 id="one-feature-crosses-several-trust-domains" tabindex="-1">One feature crosses several trust domains <a class="header-anchor" href="#one-feature-crosses-several-trust-domains" aria-label="Permalink to &quot;One feature crosses several trust domains&quot;">​</a></h2><p>The helper sits between local process execution and remote HTTP traffic. It can consume local environment and working-directory context, produce values that may be sensitive, influence network requests, interact with OAuth startup, and leave behind child processes if cancellation is poorly handled.</p><p>Each part of that path asks a different governance question:</p><ul><li><strong>Scope:</strong> where is the extension allowed to run and where may its output apply?</li><li><strong>Ownership:</strong> which request fields belong to the helper, and which remain owned by OAuth or MCP?</li><li><strong>Lifetime:</strong> when is the helper evaluated, cached, refreshed or discarded?</li><li><strong>Resource bounds:</strong> how long may it run, how much output may it produce, and what happens to child work?</li><li><strong>Observability:</strong> what may operators inspect without exposing the command or returned secrets?</li></ul><p>Treating all five as one boolean would hide the difference between “the integration is configured,” “the helper may execute here,” and “this particular request may carry the resolved output.”</p><p>The source-backed basis is <a href="https://github.com/openai/codex/commit/379cb68444057c721b6c8fa0bd610b7c6ecb9824" target="_blank" rel="noreferrer">OpenAI Codex commit <code>379cb68</code></a> and <a href="https://github.com/openai/codex/pull/38245" target="_blank" rel="noreferrer">PR #38245</a>, as captured in the same-day Reading Result and Research Object. These are public primary-source implementation records; they do not independently validate every deployment of a local helper.</p><h2 id="scope-local-admission-is-narrower-than-configuration-presence" tabindex="-1">Scope: local admission is narrower than configuration presence <a class="header-anchor" href="#scope-local-admission-is-narrower-than-configuration-presence" aria-label="Permalink to &quot;Scope: local admission is narrower than configuration presence&quot;">​</a></h2><p>The field is accepted only for streamable-HTTP MCP configuration. Stdio configuration rejects it, and pairing it with a non-local environment ID is rejected during parsing. Runtime application adds another check: a managed-disabled server or a server that is not effectively local does not run the helper.</p><p>That layered decision is useful. Parsing validates the declared shape; runtime policy validates the effective context. Neither should be mistaken for the other.</p><p>The output is also origin-scoped. Helper headers apply only when the request URL has the same origin as the configured MCP server. Cross-origin requests pass through without the helper output. For requests using helper headers, redirects are stopped so a later hop cannot silently carry the values elsewhere.</p><p>Scope is therefore more than “local process.” It includes the configuration kind, effective environment, managed policy, destination origin and redirect behavior.</p><h2 id="ownership-an-extension-may-supplement-a-protocol-without-taking-it-over" tabindex="-1">Ownership: an extension may supplement a protocol without taking it over <a class="header-anchor" href="#ownership-an-extension-may-supplement-a-protocol-without-taking-it-over" aria-label="Permalink to &quot;Ownership: an extension may supplement a protocol without taking it over&quot;">​</a></h2><p>Dynamic headers can replace same-name configured non-reserved headers, but they cannot claim protocol- or authentication-owned fields such as <code>Authorization</code>, <code>Host</code>, <code>Content-Type</code> or <code>Mcp-Session-Id</code>. The helper output must be a JSON object of string keys and values; duplicate, case-insensitive duplicate, invalid and reserved names are rejected.</p><p>This is a strong ownership boundary. The extension can supply gateway-specific material while OAuth remains responsible for its own authorization header and MCP retains its session and transport fields.</p><p>Without this separation, “custom headers” becomes an authority-escalation surface. A helper intended to add one gateway token could replace the protocol&#39;s authentication, forge a session identifier or alter content interpretation. Ownership rules make the extension additive rather than sovereign.</p><h2 id="lifetime-caching-is-a-contract-including-cached-failure" tabindex="-1">Lifetime: caching is a contract, including cached failure <a class="header-anchor" href="#lifetime-caching-is-a-contract-including-cached-failure" aria-label="Permalink to &quot;Lifetime: caching is a contract, including cached failure&quot;">​</a></h2><p>The helper result is represented as a shared future. Concurrent requests in one provider context share a single execution. Success is cached, and failure is cached as well. A later request does not silently rerun a helper that already failed.</p><p>This avoids per-request process churn and inconsistent credentials within one connection context. It also creates an explicit limitation: the implementation does not refresh the helper output after a 401 or 403, because those statuses may belong to OAuth challenges and reconnecting can discard MCP session state.</p><p>Caching is not merely an optimization. It defines the credential and failure lifetime. A production contract should make that lifetime inspectable and decide how deliberate refresh differs from automatic retry.</p><h2 id="resource-bounds-cancellation-must-own-the-process-tree" tabindex="-1">Resource bounds: cancellation must own the process tree <a class="header-anchor" href="#resource-bounds-cancellation-must-own-the-process-tree" aria-label="Permalink to &quot;Resource bounds: cancellation must own the process tree&quot;">​</a></h2><p>The helper has a ten-second execution limit and a 64 KiB stdout limit. It starts with a cleared environment, receives only the repository&#39;s permitted MCP subprocess environment, and runs in a resolved local working directory. On Unix it uses its own process group; on Windows it is placed in a containment job. Dropping the helper process terminates contained work instead of leaving it detached.</p><p>These mechanisms do not prove that an arbitrary configured command is trustworthy. They narrow the damage and lifecycle ambiguity of executing it. Timeout without process-tree ownership would still allow a grandchild to survive; output validation without an output bound would still expose memory pressure; environment clearing without destination scope would still allow network leakage.</p><p>The controls work as a set because they cover different failure modes.</p><h2 id="observability-show-the-state-without-revealing-the-secret-path" tabindex="-1">Observability: show the state without revealing the secret path <a class="header-anchor" href="#observability-show-the-state-without-revealing-the-secret-path" aria-label="Permalink to &quot;Observability: show the state without revealing the secret path&quot;">​</a></h2><p>CLI inspection renders the configured helper command as <code>&lt;redacted&gt;</code>. Validation errors reject invalid values without echoing secret content. At the same time, over-redaction can make operations impossible to diagnose.</p><p>A reviewable design should expose non-sensitive facts such as whether a helper is configured, whether it was admitted, whether resolution succeeded, when the cached result was established, which destination scope applies, and which bounded failure class occurred. It should not print the command text or returned header values by default.</p><p>The selected source does not provide a durable audit model. That gap is important. Redaction protects ordinary inspection, while auditability asks how to retain enough evidence to explain a failure later without persisting credentials.</p><h2 id="five-boundaries-form-one-extension-contract" tabindex="-1">Five boundaries form one extension contract <a class="header-anchor" href="#five-boundaries-form-one-extension-contract" aria-label="Permalink to &quot;Five boundaries form one extension contract&quot;">​</a></h2><p>The reusable pattern is a contract with independent fields rather than a single <code>enabled</code> bit:</p><ol><li><strong>Scope declaration:</strong> transport, local/remote context, managed-policy decision and destination origin.</li><li><strong>Ownership declaration:</strong> fields the extension may supply and fields reserved to the host protocol.</li><li><strong>Lifetime declaration:</strong> evaluation moment, cache scope, refresh policy and failure reuse.</li><li><strong>Resource declaration:</strong> timeout, output limit, environment, working directory and cleanup ownership.</li><li><strong>Observability declaration:</strong> safe status, redaction rules and audit metadata.</li></ol><p>These fields make design review more precise. A reviewer can approve origin scoping while rejecting an unbounded refresh policy, or accept process containment while requiring a structured executable/argument form instead of one shell command string.</p><h2 id="what-the-implementation-does-not-establish" tabindex="-1">What the implementation does not establish <a class="header-anchor" href="#what-the-implementation-does-not-establish" aria-label="Permalink to &quot;What the implementation does not establish&quot;">​</a></h2><p>The evidence covers one local streamable-HTTP MCP path. It does not establish a universal credential-injection protocol, remote-environment safety, durable auditability or trustworthiness of arbitrary helpers. The command may remain visible through local process or configuration inspection even though CLI output is redacted. Cached values can expire, and the source intentionally has no rejection-driven refresh.</p><p>The bounded conclusion is therefore architectural: dynamic integrations should expose separate scope, ownership, lifetime, resource and observability boundaries. Whether a particular integration is safe still depends on the helper, host policy, deployment and threat model.</p><h2 id="open-engineering-questions" tabindex="-1">Open engineering questions <a class="header-anchor" href="#open-engineering-questions" aria-label="Permalink to &quot;Open engineering questions&quot;">​</a></h2><ul><li>What explicit, session-preserving refresh event should replace automatic rerun after 401/403?</li><li>Which non-sensitive execution facts should become durable audit evidence?</li><li>Can a structured executable-and-arguments declaration reduce shell ambiguity without losing deployment flexibility?</li><li>What proof should be required before allowing safe same-origin redirects?</li></ul><p>Extensibility becomes reviewable when those questions have named places in the contract. A permission switch can open the door; it cannot describe the room, the owner, the clock, the budget or the audit trail.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><a href="https://github.com/openai/codex/commit/379cb68444057c721b6c8fa0bd610b7c6ecb9824" target="_blank" rel="noreferrer">OpenAI Codex commit <code>379cb684</code>: constrained dynamic MCP HTTP-header helper</a></li><li><a href="https://github.com/openai/codex/pull/38245" target="_blank" rel="noreferrer">OpenAI Codex PR #38245</a></li><li><code>research/reading/Q-20260813-03-constrained-mcp-http-header-helper.md</code></li><li><code>research/analysis/Q-20260813-03-extension-boundary.md</code></li></ul>',43))])}const f=i(c,[["render",l]]);export{b as __pageData,f as default};
